-- =====================================================================
-- khaustan_menu_data_KrishnaBhog_400708001_KhaustanRestaurantMenu.sql
--
-- RESTAURANT : Krishna Bhog
--              Krishna Bhog, near Euro School, Sector-19, Airoli, Navi Mumbai, Maharashtra 400708, India
-- IDS        : establishment_id = restaurant_id = source_id = 400708001 (given directly in the JSON)
-- SOURCE     : Krishna_Bhog_Menu_OCR.json (OCR JSON, 18 menu-page images)
-- TARGET     : PostgreSQL, database "KhaustanRestaurantMenu" (one transaction)
-- SCHEMA REF : khaustan-KhaustanRestaurantMenu-Create_DB-postgresql.sql
-- LOOKUP REF : khaustan_lookup_data_seed_KhaustanRestaurantMenu.sql (READ-ONLY - see below)
-- NOT FROM A BRAND: no brand row is created or referenced, per instruction.
--
-- HOW TO RUN  psql -v ON_ERROR_STOP=1 -f <this file>
--             Run it once in a disposable/staging database first. It could not be executed
--             against PostgreSQL where it was produced.
--
-- LOOKUP TABLES ARE READ-ONLY IN THIS SCRIPT. It never inserts, updates or deletes a
-- protein_type row - it only reads it by code. The pre-flight check aborts before writing
-- anything if the row it needs is missing.
--
-- ID SCHEME: establishment_id = restaurant_id = source_id = 400708001. menu_board, menu_category,
-- menu_item, menu_item_variant, menu_item_price and menu_board_item each use their OWN counter,
-- starting at 400708001001 = 400708001*1000+1 and incrementing by 1 in source order within that
-- table. menu_item_availability uses the same scheme but only has 2 rows (see note 5).
-- addon_group/addon_option, canonical_dish(_id/_name) use the schema's ordinary
-- application-generated approach (one helper sequence).
--
-- ROWS LOADED
--   establishment 1 | restaurant 1 | restaurant_delivery 1 | source_record 1
--   menu_extraction_batch 1 | menu_board 1 | menu_category 30 | menu_board_category 30
--   canonical_dish up to 252 | menu_item 256 | menu_item_source 256
--   menu_item_variant 256 | menu_item_price 256 | menu_item_price_source 256
--   menu_item_availability 2 | addon_group 1 | addon_option 1
--   menu_item_addon_group 18 | menu_board_item 256
--
-- CONVENTIONS / JUDGEMENT CALLS
--  1. Every item in this JSON has one plain price (no Full/Half, no protein split anywhere in
--     this menu) -> one menu_item, one 'Regular' variant, one price each - the simplest shape
--     used across the restaurants onboarded so far.
--  2. food_classification_code: the menu's own cover page says "Veg Restaurant", and 254 of
--     256 items are indeed vegetarian with nothing in the JSON to contradict it - but two
--     items (Tomato Omelet, Tomato Cheese Omelet, both under SNACKS) are plainly egg dishes by
--     their own printed name, directly contradicting that label. Classification is therefore
--     taken from each item's own name (veg by the restaurant-wide default, egg for those two),
--     not asserted uniformly from the banner - and restaurant.veg_nonveg_status is set to
--     'veg_and_nonveg' rather than 'pure_veg', since the menu's own content is not, in fact,
--     purely vegetarian. protein_type_id is NULL throughout (not needed for veg items, and the
--     schema's protein_type lookup has no separate "egg" distinct from the EGG code already
--     used). is_jain / is_vegan / is_eggless / spice_level are NULL everywhere - nothing in the
--     JSON asserts them for any specific item (see note 6 on the two general Jain notes).
--  3. Canonical dishes: exact-normalized-name match, 252 distinct dishes. "Rose" and
--     "Kesar" each print once under MILK SHAKES and once under FALOODA with no distinguishing
--     text - per the same standing rule used for every restaurant onboarded so far, a name
--     recurring across different categories is treated as a possibly-different product each
--     time, so all 4 of these rows are left with canonical_dish_id = NULL.
--  4. GST: "GST Taxes as applicable" is printed on every page that has menu items (16 of 18 -
--     the other 2 are the cover and closing pages, which have no items at all) -> applied as a
--     restaurant-wide policy to every menu_item_price row: tax_regime_code = 'GST',
--     tax_inclusion_code = 'exclusive' (the shown price does not include tax), tax_rate left
--     NULL (no percentage is stated, only "as applicable").
--  5. "(Tea and coffee till 7.30 pm)" (page 16, BEVERAGES) names only Tea and Coffee, not the
--     whole section - menu_item_availability rows are added for exactly those two items
--     (end_time = 19:30, day_of_week and start_time NULL - no day restriction or start time is
--     stated).
--  6. "(All above With Butter Rs.9/- Extra)" (page 13) sits between the DAL and ROTI / NAAN
--     sections printed on that same page and reads naturally as covering both - one addon_group
--     ("Butter Add-on", selection_type 'single', not required) with one addon_option ("Butter",
--     Rs.9), linked to all 18 items across both sections.
--  7. "(Jain Sandwich Available)" (page 3) and "(Jain Available)" (page 4, covering PAV BHAJI
--     and PIZZA) are general notes that a Jain version can be requested - neither names which
--     specific item(s), so no is_jain flag is set on any single item; see the trailing notes.
--  8. Hours: the JSON's own "timing" field says "8:00 am to 12:00 pm", applied to every day of
--     the week. As with the only other restaurant seen with this exact same string, a 4-hour
--     morning-only window is implausible for a full-menu, dinner-oriented restaurant, and it
--     directly conflicts with this menu's own "(Tea and coffee till 7.30 pm)" note (which could
--     not apply if the restaurant were never open past noon). Loaded exactly as printed rather
--     than guessed at.
-- =====================================================================

--\connect "KhaustanRestaurantMenu"
\set ON_ERROR_STOP on

BEGIN;

-- ---------------------------------------------------------------------
-- 0. Helper sequence (non-mandatory standalone IDs only) + PRE-FLIGHT
-- ---------------------------------------------------------------------
DO $seq$
DECLARE
    v_max BIGINT;
BEGIN
    SELECT GREATEST(
        COALESCE((SELECT MAX(extraction_batch_id) FROM menu_extraction_batch), 0),
        COALESCE((SELECT MAX(canonical_dish_id) FROM canonical_dish), 0),
        COALESCE((SELECT MAX(canonical_dish_name_id) FROM canonical_dish_name), 0),
        COALESCE((SELECT MAX(addon_group_id) FROM addon_group), 0),
        COALESCE((SELECT MAX(addon_option_id) FROM addon_option), 0)
    ) INTO v_max;
    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS khaustan_krishnabhog_helper_seq START WITH %s', v_max + 1);
END
$seq$;

DO $pre$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM protein_type WHERE code = 'EGG') THEN
        RAISE EXCEPTION 'Krishna Bhog load aborted - lookup row missing: protein_type.EGG. Run the lookup seed script first.';
    END IF;

    IF EXISTS (SELECT 1 FROM menu_item WHERE restaurant_id = 400708001)
       OR EXISTS (SELECT 1 FROM menu_extraction_batch WHERE restaurant_id = 400708001)
       OR EXISTS (SELECT 1 FROM source_record WHERE source_id = 400708001) THEN
        RAISE EXCEPTION 'Krishna Bhog (restaurant_id 400708001) already has menu data or source_id 400708001 is in use - refusing to load twice.';
    END IF;

    IF EXISTS (SELECT 1 FROM establishment WHERE establishment_id = 400708001)
       OR EXISTS (SELECT 1 FROM restaurant WHERE restaurant_id = 400708001) THEN
        RAISE EXCEPTION 'establishment_id/restaurant_id 400708001 is already in use by a different row - resolve before loading.';
    END IF;
END
$pre$;

-- ---------------------------------------------------------------------
-- 1. Establishment + restaurant (no brand). city is explicitly "Navi Mumbai" here, overriding
--    the schema's own 'Mumbai' default, since that is what the JSON's address actually says.
-- ---------------------------------------------------------------------
INSERT INTO establishment (establishment_id, name, normalized_name, address_line1, locality, city, postal_code, state, latitude, longitude)
SELECT 400708001, 'KRISHNA BHOG', 'krishna bhog', 'Krishna Bhog, near Euro School, Sector-19', 'Airoli', 'Navi Mumbai', '400708', 'Maharashtra', 19.15751934940668, 72.99302568525432
WHERE NOT EXISTS (SELECT 1 FROM establishment WHERE establishment_id = 400708001);

INSERT INTO restaurant (restaurant_id, establishment_id, display_name, normalized_name, veg_nonveg_status, has_bar, bar_license_type)
SELECT 400708001, 400708001, 'KRISHNA BHOG', 'krishna bhog', 'veg_and_nonveg', FALSE, 'none'
WHERE NOT EXISTS (SELECT 1 FROM restaurant WHERE restaurant_id = 400708001);

