-- ---------------------------------------------------------------------
-- 16. POST-LOAD CHECK (raises -> whole transaction rolls back)
-- ---------------------------------------------------------------------
DO $post$
DECLARE
    n_cat bigint; n_item bigint; n_var bigint; n_price bigint; n_bc bigint; n_bi bigint;
    n_avail bigint; n_addon bigint;
BEGIN
    SELECT count(*) INTO n_cat FROM menu_category WHERE restaurant_id = 400708001;
    SELECT count(*) INTO n_item FROM menu_item WHERE restaurant_id = 400708001;
    SELECT count(*) INTO n_var FROM menu_item_variant v JOIN menu_item i ON i.menu_item_id = v.menu_item_id WHERE i.restaurant_id = 400708001;
    SELECT count(*) INTO n_price FROM menu_item_price p JOIN menu_item_variant v ON v.variant_id = p.variant_id JOIN menu_item i ON i.menu_item_id = v.menu_item_id WHERE i.restaurant_id = 400708001;
    SELECT count(*) INTO n_bc FROM menu_board_category WHERE restaurant_id = 400708001;
    SELECT count(*) INTO n_bi FROM menu_board_item WHERE restaurant_id = 400708001;
    SELECT count(*) INTO n_avail FROM menu_item_availability a JOIN menu_item i ON i.menu_item_id = a.menu_item_id WHERE i.restaurant_id = 400708001;
    SELECT count(*) INTO n_addon FROM menu_item_addon_group mag JOIN menu_item i ON i.menu_item_id = mag.menu_item_id WHERE i.restaurant_id = 400708001;

    IF n_cat <> 30 OR n_item <> 256 OR n_var <> 256 OR n_price <> 256
       OR n_bc <> 30 OR n_bi <> 256 OR n_avail <> 2 OR n_addon <> 18 THEN
        RAISE EXCEPTION 'Krishna Bhog post-load check failed: categories=%, items=%, variants=%, prices=%, board_categories=%, board_items=%, availability=%, addon_links=%',
            n_cat, n_item, n_var, n_price, n_bc, n_bi, n_avail, n_addon;
    END IF;

    RAISE NOTICE 'Krishna Bhog loaded: % categories, % items, % variants, % prices', n_cat, n_item, n_var, n_price;
END
$post$;

COMMIT;

